import java.lang.annotation.*;import java.lang.reflect.*;@Retention(RetentionPolicy.RUNTIME)@Target(ElementType.FIELD)@interface NotBlank{}@Retention(RetentionPolicy.RUNTIME)@Target(ElementType.FIELD)@interface MaxLength{int value();}class SignupForm{@NotBlank @MaxLength(12) String name="";@NotBlank String email="a@b.com";}public class FormValidator{public static void main(String[]x)throws Exception{SignupForm f=new SignupForm();for(Field a:f.getClass().getDeclaredFields()){a.setAccessible(true);Object v=a.get(f);if(a.isAnnotationPresent(NotBlank.class)&&v.toString().isBlank())System.out.println(a.getName()+" required");if(a.isAnnotationPresent(MaxLength.class)&&v.toString().length()>a.getAnnotation(MaxLength.class).value())System.out.println(a.getName()+" too long");}}}
